{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7fbf9;--card:#ffffff;--muted:#6b7280;--accent:#2b7a78;--accent-2:#7cc6bf;--glass:rgba(255,255,255,0.7);font-family:Inter,system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif}
    html,body{height:100%;margin:0;background:linear-gradient(180deg,var(--bg),#eef7f6);color:#073642}
    .page{min-height:100%;display:flex;flex-direction:column}
    header{display:flex;align-items:center;justify-content:space-between;padding:20px 28px}
    .brand{display:flex;align-items:center;gap:12px}
    .logo{width:48px;height:48px;background:var(--accent);display:flex;align-items:center;justify-content:center;color:#fff;border-radius:8px;font-weight:700}
    nav a{margin-left:18px;color:var(--muted);text-decoration:none;font-size:14px}
    .hero{display:grid;grid-template-columns:1fr 380px;gap:28px;padding:28px;align-items:center}
    .panel{background:linear-gradient(180deg,var(--card),#fbffff);padding:24px;border-radius:12px;box-shadow:0 6px 18px rgba(11,22,23,0.06)}
    h1{margin:0 0 10px 0;font-size:28px;color:#053d3d}
    p.lead{margin:0 0 16px 0;color:var(--muted)}
    .membership-note{font-size:13px;color:var(--accent);font-weight:600;margin-bottom:12px}
    .pillars{display:flex;gap:12px;margin-top:14px}
    .pill{flex:1;padding:12px;border-radius:10px;background:linear-gradient(180deg,#fff,#f7fffd);border:1px solid #e6f2f1}
    .muted{color:var(--muted);font-size:14px}
    /* small interactive UI */
    .selector{display:flex;flex-direction:column;gap:10px}
    select,button,input[type="checkbox"]{font:inherit}
    select{padding:10px;border-radius:8px;border:1px solid #cfe6e4;background:#fff}
    .cta{display:inline-flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;border:0;background:var(--accent);color:#fff;font-weight:600;cursor:pointer}
    .secondary{background:#fff;border:1px solid #cfe6e4;color:var(--accent)}
    .method-card{margin-top:12px;padding:12px;background:linear-gradient(90deg,#f8fffd,#ffffff);border-radius:10px;border:1px solid #e1f3ef}
    footer{padding:20px 28px;margin-top:auto;color:var(--muted);font-size:13px}
    /* progress map small */
    .path-map{margin-top:16px}
    .steps{display:flex;gap:8px}
    .step{flex:1;padding:8px;border-radius:8px;background:#eaf6f4;text-align:center;font-size:12px}
    .meta{font-size:12px;color:var(--muted);margin-top:8px}
    /* decorative */
    .pattern{position:absolute;right:0;top:0;width:360px;height:240px;opacity:0.12}
    @media(max-width:880px){.hero{grid-template-columns:1fr;padding:18px}.pattern{display:none};nav a{display:none}}
  </style>
</head>
<body>
  <div class="page">
    <header>
      <div class="brand">
        <div class="logo">W</div>
        <div>
          <div style="font-weight:700">{{BUSINESS_NAME}}</div>
          <div style="font-size:12px;color:var(--muted)">{{CITY}}, {{STATE}}</div>
        </div>
      </div>
      <nav>
        <a href="index.html">Overview</a>
        <a href="services.html">Ways I Help</a>
        <a href="programs.html">Programs</a>
        <a href="pricing.html">Plans</a>
        <a href="contact.html">Reach</a>
      </nav>
    </header>

    <main class="hero">
      <section class="panel">
        <div class="membership-note">Membership access • ongoing guidance</div>
        <h1>Help that meets you where you are</h1>
        <p class="lead">We turn routine micro-choices into reliable momentum. Membership preserves access to frameworks, weekly tuning, and short actionable cycles so you can steward energy across busy weeks.</p>
        <div class="pillars">
          <div class="pill"><strong>Outcomes</strong>
            <div class="muted">Clear markers for the next 30, 60, 90 days.</div>
          </div>
          <div class="pill"><strong>Habits</strong>
            <div class="muted">Micro-practices that fit your schedule.</div>
          </div>
          <div class="pill"><strong>Frameworks</strong>
            <div class="muted">A repeatable scaffolding for everyday choices.</div>
          </div>
        </div>

        <div style="margin-top:18px">
          <div class="selector">
            <label style="font-weight:700">Mood-to-Method</label>
            <select id="moodSelect" aria-label="Choose mood">
              <option value="steady">Steady, want to preserve</option>
              <option value="low">Low energy — gentle rebuild</option>
              <option value="rushed">Rushed — priority triage</option>
              <option value="restless">Restless — reset rhythm</option>
              <option value="clear">Clear & ready — accelerate</option>
            </select>
            <div class="method-card" id="methodCard">
              <div style="font-weight:700" id="methodName">Balanced Track</div>
              <div class="meta" id="methodDesc">A steady plan: short daily anchors, weekly check-ins to keep gains without overhauling life.</div>
            </div>
            <div style="margin-top:12px">
              <button id="primaryCta" class="cta">{{PRIMARY_CTA_LABEL}}</button>
              <button class="cta secondary" onclick="location.href='contact.html'">Ask a question</button>
            </div>
          </div>
        </div>

      </section>

      <aside class="panel">
        <div style="font-size:13px;color:var(--muted);font-weight:600">Your 30-day path</div>
        <div class="path-map" id="smallMap">
          <div class="steps" id="mapSteps">
            <div class="step">Days 1–5<br><small>Set anchors</small></div>
            <div class="step">Days 6–10<br><small>Small builds</small></div>
            <div class="step">Days 11–15<br><small>Habit link</small></div>
            <div class="step">Days 16–20<br><small>Sustain</small></div>
            <div class="step">Days 21–25<br><small>Adjust</small></div>
            <div class="step">Days 26–30<br><small>Review</small></div>
          </div>
          <div class="meta">Pick a mood above and the path will adjust — try "Rushed" to see a triage-friendly map.</div>
        </div>

        <div style="margin-top:18px;font-size:13px;color:var(--muted)">
          Membership grants weekly templates, short labs, and monthly tuning calls so changes stick.
        </div>
      </aside>

      <svg class="pattern" viewBox="0 0 200 120" xmlns="http://www.w3.org/2000/svg" aria-hidden>
        <defs>
          <linearGradient id="g1" x1="0" x2="1">
            <stop stop-color="#bfeae6" offset="0"/>
            <stop stop-color="#eafaf8" offset="1"/>
          </linearGradient>
        </defs>
        <rect width="200" height="120" rx="10" fill="url(#g1)"/>
        <g fill="#fff" opacity="0.55">
          <circle cx="45" cy="30" r="18"/>
          <circle cx="80" cy="70" r="12"/>
          <rect x="110" y="20" width="60" height="10" rx="3"/>
        </g>
      </svg>

    </main>

    <footer>
      <div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap">
        <div>Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
        <div style="font-size:13px;color:var(--muted)">© <span id="yr"></span> All rights reserved</div>
      </div>
    </footer>
  </div>

  <script>
    (function(){
      document.getElementById('yr').textContent = new Date().getFullYear();
      var mood = document.getElementById('moodSelect');
      var methodName = document.getElementById('methodName');
      var methodDesc = document.getElementById('methodDesc');
      var cta = document.getElementById('primaryCta');
      var mapSteps = document.getElementById('mapSteps');

      var methods = {
        steady:{name:'Balanced Track',desc:'Short anchors and light weekly practice to keep the gains going.',cta:'Continue with membership'},
        low:{name:'Gentle Rebuild',desc:'Slow ramp: two daily anchors, 3–10 minute practices, clear energy-first targets.',cta:'Try the gentle plan'},
        rushed:{name:'Triage Flow',desc:'Prioritize 3 actions: quick breathing, a tiny movement, and a single decision-within-24h.',cta:'Start the triage flow'},
        restless:{name:'Rhythm Reset',desc:'Shift timing and small rituals to calm the day and make ease predictable.',cta:'Begin a 2-week reset'},
        clear:{name:'Momentum Push',desc:'Use existing capacity to add short accelerators and weekly labs for growth.',cta:'Join the momentum lab'}
      };

      function updateByMood(key){
        var m = methods[key] || methods.steady;
        methodName.textContent = m.name;
        methodDesc.textContent = m.desc;
        cta.textContent = m.cta + ' — {{PRIMARY_CTA_LABEL}}';
        // adjust small path tiles to reflect tone
        var labels = {
          steady:['Anchor','Tune','Hold','Review','Sustain','Reflect'],
          low:['Tiny Start','Gentle Up','Link','Sustain','Ease','Check-in'],
          rushed:['Quick Triage','Essential Only','Simplify','Hold','Fast Adjust','Review'],
          restless:['Shift Timing','New Anchor','Slow Build','Stabilize','Refine','Reset'],
          clear:['Launch','Ramp','Accelerate','Double Down','Sharpen','Assess']
        };
        var chosen = labels[key] || labels.steady;
        var children = mapSteps.children;
        for(var i=0;i<children.length;i++){children[i].innerHTML = 'Days '+(i*5+1)+'–'+(i*5+5)+'<br><small>'+chosen[i]+'</small>'}
      }

      mood.addEventListener('change',function(e){updateByMood(e.target.value)});
      // initial
      updateByMood(mood.value);

      // CTA navigates to join with a query param describing method
      cta.addEventListener('click',function(){
        var q = encodeURIComponent(methodName.textContent);
        location.href = '{{PRIMARY_CTA_URL}}?method='+q;
      });
    })();
  </script>
</body>
</html>"} 
{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Ways I Help — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff9f8;--card:#ffffff;--muted:#5b6165;--accent:#a64b4b;--calm:#ffdede;font-family:Inter,system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif}
    body{margin:0;background:linear-gradient(180deg,var(--bg),#fff);color:#2b2b2b}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 26px}
    .logo{width:44px;height:44px;border-radius:8px;background:var(--accent);color:#fff;display:flex;align-items:center;justify-content:center;font-weight:700}
    nav a{margin-left:16px;color:var(--muted);text-decoration:none;font-size:13px}
    .grid{display:grid;grid-template-columns:1fr 320px;gap:22px;padding:18px}
    .panel{background:var(--card);padding:18px;border-radius:12px;border:1px solid #f0e2e2}
    h2{margin:0 0 8px 0}
    .service{display:flex;gap:12px;padding:12px;border-radius:10px;margin-bottom:10px;border:1px dashed #f6e5e5}
    .icon{width:56px;height:56px;border-radius:8px;background:#fff3f3;display:flex;align-items:center;justify-content:center;font-weight:700;color:var(--accent)}
    .meta{font-size:13px;color:var(--muted)}
    .goals{display:flex;flex-direction:column;gap:8px;margin-top:12px}
    .goal{display:flex;align-items:center;gap:8px}
    .map{margin-top:14px;padding:12px;border-radius:10px;background:linear-gradient(90deg,#fff,#fff5f5);border:1px solid #ffecec}
    .timeline{display:flex;gap:6px;margin-top:8px}
    .dot{flex:1;height:12px;border-radius:6px;background:#ffecec}
    .percent{font-weight:700;margin-top:8px}
    .note{font-size:13px;color:var(--muted);margin-top:10px}
    .cta{margin-top:12px;padding:10px 12px;border-radius:10px;border:0;background:var(--accent);color:#fff;cursor:pointer}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Support designed for real days</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Intro</a>
      <a href="about.html">Approach</a>
      <a href="programs.html">Offerings</a>
      <a href="book.html">Book</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="grid">
    <section class="panel">
      <h2>Ways I Help</h2>
      <p class="meta">Short engagements, ongoing membership, and focused labs — each service is framed around outcomes and daily practice, not one-size-fits-all advice.</p>

      <div class="service">
        <div class="icon">M1</div>
        <div>
          <div style="font-weight:700">Monthly Membership — Foundation</div>
          <div class="meta">Ongoing templates, weekly check-ins, and monthly tuning sessions for steady progress.</div>
        </div>
      </div>

      <div class="service">
        <div class="icon">L2</div>
        <div>
          <div style="font-weight:700">Short Lab — Reset 2-Week</div>
          <div class="meta">A tightly framed lab with daily micro-practices and two live check-ins.</div>
        </div>
      </div>

      <div class="service">
        <div class="icon">C3</div>
        <div>
          <div style="font-weight:700">Momentum Coaching — 12 Weeks</div>
          <div class="meta">Goal-driven cycles, clear weekly deliverables, and an accountability framework.</div>
        </div>
      </div>

      <div style="margin-top:14px;font-size:14px">
        <div style="font-weight:700">How we design your first month</div>
        <div class="meta">We pick two measurable outcomes and tie three tiny habits to daily life. The map below adapts when you select goals.</div>

        <form id="goalForm" class="goals" onsubmit="return false;">
          <label class="goal"><input type="checkbox" name="goal" value="energy"> More steady energy</label>
          <label class="goal"><input type="checkbox" name="goal" value="sleep"> Better sleep rhythm</label>
          <label class="goal"><input type="checkbox" name="goal" value="stress"> Easier stress handling</label>
          <label class="goal"><input type="checkbox" name="goal" value="focus"> Clearer focus blocks</label>
          <label class="goal"><input type="checkbox" name="goal" value="movement"> Move more without strain</label>
        </form>

        <div class="map" id="goalMap">
          <div style="font-weight:700">30-day path preview</div>
          <div id="timeline" class="timeline">
            <div class="dot" style="background:#f0e0e0"></div>
            <div class="dot" style="background:#f0e0e0"></div>
            <div class="dot" style="background:#f0e0e0"></div>
            <div class="dot" style="background:#f0e0e0"></div>
            <div class="dot" style="background:#f0e0e0"></div>
            <div class="dot" style="background:#f0e0e0"></div>
          </div>
          <div id="progressPct" class="percent">Select goals to see a plan</div>
          <div class="note">Tip: choosing 2–3 targets produces the most tangible change in 30 days.</div>
        </div>

        <button id="joinBtn" class="cta">{{PRIMARY_CTA_LABEL}}</button>
      </div>
    </section>

    <aside class="panel">
      <h3 style="margin:0 0 8px 0">Quick diagnostic</h3>
      <p class="meta">Answer two short prompts and get a suggested starting offer.</p>
      <div style="margin-top:12px">
        <label style="display:block;margin-bottom:8px">Pick the description that fits you now</label>
        <select id="diagMood" style="padding:10px;border-radius:8px;border:1px solid #efe0e0;width:100%">
          <option value="explore">Exploring membership</option>
          <option value="rebuild">Want to rebuild energy</option>
          <option value="accelerate">Ready to accelerate progress</option>
        </select>
        <div style="margin-top:12px">
          <button id="diagCta" class="cta">Get recommendation</button>
        </div>
        <div style="margin-top:12px;font-size:13px;color:var(--muted)" id="diagResult">No recommendation yet.</div>
      </div>

      <div style="margin-top:18px;font-size:13px;color:var(--muted)">Contact: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
    </aside>
  </main>

  <script>
    (function(){
      var checkboxes = Array.from(document.querySelectorAll('input[name="goal"]'));
      var timeline = document.getElementById('timeline');
      var pct = document.getElementById('progressPct');
      var joinBtn = document.getElementById('joinBtn');

      function updateMap(){
        var selected = checkboxes.filter(function(c){return c.checked}).map(function(c){return c.value});
        // percent roughly scales: 1 goal = 30%, 2 goals = 55%, 3 = 75%, 4 = 90%, 5 = 100%
        var p = 0;
        switch(selected.length){case 0:p=0;break;case 1:p=30;break;case 2:p=55;break;case 3:p=75;break;case 4:p=90;break;case 5:p=100;break}
        pct.textContent = (p===0)?'Select goals to see a plan':('Estimated progress: '+p+'%');
        var colors = ['#ffdede','#ffe9e9','#ffcccc','#ffc2c2','#ffb3b3','#ffa3a3'];
        for(var i=0;i<timeline.children.length;i++){
          timeline.children[i].style.background = (i < Math.ceil(p/20))?colors[i%colors.length]:'#f0e0e0';
        }
        // create short plan details in join button query
        var label = '{{PRIMARY_CTA_LABEL}}';
        if(selected.length===0) joinBtn.textContent = label;
        else joinBtn.textContent = (selected.length<=2? 'Join: focus plan' : 'Join: multi-target plan') + ' — '+label;
      }

      checkboxes.forEach(function(c){c.addEventListener('change',updateMap)});
      updateMap();

      // diagnostic mini flow
      document.getElementById('diagCta').addEventListener('click',function(){
        var mood = document.getElementById('diagMood').value;
        var out = 'Recommended: Membership — Foundation';
        if(mood==='rebuild') out = 'Recommended: Short Lab — Reset 2-Week';
        if(mood==='accelerate') out = 'Recommended: Momentum Coaching — 12 Weeks';
        document.getElementById('diagResult').textContent = out;
      });

      // join button navigates
      joinBtn.addEventListener('click',function(){
        var q = encodeURIComponent(document.getElementById('progressPct').textContent);
        location.href = '{{PRIMARY_CTA_URL}}?plan='+q;
      });
    })();
  </script>
</body>
</html>"} 
{"path":"programs.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Programs — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f5fbff;--card:#ffffff;--muted:#425056;--accent:#206a8b;--accent-2:#9ed3e3;font-family:Inter,system-ui,Segoe UI,Roboto,Helvetica,Arial,sans-serif}
    body{margin:0;background:var(--bg);color:#052b33}
    header{display:flex;justify-content:space-between;align-items:center;padding:18px 24px}
    .logo{background:var(--accent);width:44px;height:44px;border-radius:8px;color:#fff;display:flex;align-items:center;justify-content:center}
    nav a{margin-left:14px;color:var(--muted);text-decoration:none;font-size:14px}
    .wrap{max-width:980px;margin:18px auto;padding:0 18px}
    .grid{display:grid;grid-template-columns:2fr 1fr;gap:18px}
    .card{background:var(--card);padding:16px;border-radius:12px;border:1px solid #e5f2f6}
    h1{margin:0 0 8px 0}
    .program{border-radius:10px;padding:12px;margin-bottom:12px;border-left:4px solid transparent}
    .prog-title{display:flex;justify-content:space-between;align-items:center}
    .price{font-weight:800;color:var(--accent)}
    .desc{color:var(--muted);font-size:14px}
    .cta{padding:10px 12px;border-radius:10px;border:0;background:var(--accent);color:#fff;cursor:pointer}
    .meter{margin-top:12px;padding:12px;background:linear-gradient(90deg,#f7feff,#ffffff);border-radius:10px;border:1px solid #e2f7fb}
    .timeline{display:flex;gap:8px;margin-top:8px}
    .block{flex:1;height:12px;border-radius:6px;background:#e6f7fb}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:12px">
      <div class="logo">W</div>
      <div>
        <div style="font-weight:700">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">Program catalog</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Home</a>
      <a href="about.html">About</a>
      <a href="services.html">Services</a>
      <a href="pricing.html">Plans</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="grid">
      <section class="card">
        <h1>Offerings built around what changes habit</h1>
        <p class="desc">Each program pairs measurable outcomes with daily micro-steps and weekly reflection. Pick a lane and the onboarding map adapts to your priorities.</p>

        <div id="programList">
          <div class="program" data-plan="rhythm" style="border-left-color:#9ed3e3">
            <div class="prog-title"><div>
              <div style="font-weight:800">Rhythm Membership</div>
              <div class="desc">Ongoing templates, monthly tuning calls, and a library of short labs.</div>
            </div><div class="price">Member</div></div>
            <div style="margin-top:8px">
              <button class="cta join" data-plan="rhythm">Join — Start with a 30-day map</button>
            </div>
          </div>

          <div class="program" data-plan="reset" style="border-left-color:#c9e9d9">
            <div class="prog-title"><div>
              <div style="font-weight:800">Reset Two-Week Lab</div>
              <div class="desc">A focused 14-day protocol with daily prompts and two live sessions.</div>
            </div><div class="price">Short</div></div>
            <div style="margin-top:8px"><button class="cta join" data-plan="reset">Reserve spot</button></div>
          </div>

          <div class="program" data-plan="momentum" style="border-left-color:#ffd9b3">
            <div class="prog-title"><div>
              <div style="font-weight:800">Momentum Cycle — 12 weeks</div>
              <div class="desc">Build toward a specific outcome with weekly milestones and deliverables.</div>
            </div><div class="price">Intensive</div></div>
            <div style="margin-top:8px"><button class="cta join" data-plan="momentum">Request onboarding</button></div>
          </div>
        </div>

        <div style="margin-top:14px" class="meter">
          <div style="font-weight:700">Design your next 30 days</div>
          <div style="margin-top:8px">Choose two goals and a rhythm below to see a tailored path map.</div>

          <div style="display:flex;gap:10px;margin-top:12px">
            <select id="primaryGoal" style="padding:8px;border-radius:8px;border:1px solid #dfeff4">
              <option value="energy">Steady energy</option>
              <option value="sleep">Sleep pattern</option>
              <option value="stress">Stress handling</option>
              <option value="focus">Focus blocks</option>
            </select>
            <select id="secondaryGoal" style="padding:8px;border-radius:8px;border:1px solid #dfeff4">
              <option value="movement">Move more</option>
              <option value="habits">Form a single habit</option>
              <option value="timing">Better daily timing</option>
              <option value="mini">Micro-rests</option>
            </select>
          </div>

          <div class="timeline" id="progTimeline">
            <div class="block"></div>
            <div class="block"></div>
            <div class="block"></div>
            <div class="block"></div>
            <div class="block"></div>
            <div class="block"></div>
          </div>

          <div id="planBlurb" style="margin-top:10px;color:var(--muted)">Pick goals to preview a day-by-day micro-plan and arrival markers.</div>

        </div>

      </section>

      <aside class="card">
        <div style="font-weight:700">Program quick view</div>
        <div style="margin-top:8px;color:var(--muted)">Select a program to see a 30-day starter and the recommended pace.</div>

        <div id="programPreview" style="margin-top:14px;padding:10px;border-radius:10px;background:linear-gradient(180deg,#f7feff,#fff)"></div>

