  <script>
    (function(){
      var joins = Array.from(document.querySelectorAll('.join'));
      var preview = document.getElementById('programPreview');
      var timeline = document.getElementById('progTimeline');
      var planBlurb = document.getElementById('planBlurb');
      var primary = document.getElementById('primaryGoal');
      var secondary = document.getElementById('secondaryGoal');

      function showProgram(plan){
        var templates = {
          rhythm:'Rhythm Membership: Monthly templates + 1 tuning call. Start with two anchors and a weekly check-in — ideal for gradual change.',
          reset:'Reset Two-Week Lab: Daily micro-prompts, short practices, and two live sessions. Designed for quick recalibration.',
          momentum:'Momentum Cycle: 12-week goal-driven program with concrete weekly deliverables and accountability touchpoints.'
        };
        preview.textContent = templates[plan] || 'Select a program to preview details.';
      }

      joins.forEach(function(b){b.addEventListener('click',function(){
        var plan = b.getAttribute('data-plan');
        showProgram(plan);
        // navigate with plan
        location.href = '{{PRIMARY_CTA_URL}}?offer='+encodeURIComponent(plan);
      })});

      function updateTimeline(){
        var a = primary.value; var b = secondary.value;
        // build simple micro-habit schedule text
        var lines = [];
        lines.push('Primary target: '+a+'. Secondary target: '+b+'.');
        lines.push('Days 1–7: Establish anchors (5–10 minutes daily).');
        lines.push('Days 8–14: Link new action to existing routine.');
        lines.push('Days 15–21: Add a micro-review and small adjustment.');
        lines.push('Days 22–30: Solidify and plan a maintenance rhythm.');
        planBlurb.textContent = lines.join(' ');
        // color blocks according to selections
        var blocks = Array.from(timeline.children);
        var colors = {'energy':'#bfe8e9','sleep':'#cfe4ff','stress':'#ffe8d6','focus':'#e8fbe8','movement':'#ffe9f0','habits':'#f0f7ff','timing':'#fff6e0','mini':'#f7fff4'};
        var primaryColor = colors[a] || '#e6f7fb';
        var secondaryColor = colors[b] || '#f0e0e0';
        blocks.forEach(function(el,i){
          el.style.background = (i%2===0)?primaryColor:secondaryColor;
        });
      }

      primary.addEventListener('change',updateTimeline);
      secondary.addEventListener('change',updateTimeline);
      updateTimeline();

    })();
  </script>
